boolean tableinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\ptable"), bsname);

    if (!newfunctionprocessor(bsname, &table_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\pmove"), tabv_move);
    ADD_VERB(BIGSTRING("\pcopy"), tabv_copy);
    ADD_VERB(BIGSTRING("\prename"), tabv_rename);
    ADD_VERB(BIGSTRING("\pmoveandrename"), tabv_moveandrename);
    ADD_VERB(BIGSTRING("\passign"), tabv_assign);
    ADD_VERB(BIGSTRING("\pvalidate"), tabv_validate);
    ADD_VERB(BIGSTRING("\psortby"), tabv_sortby);
    ADD_VERB(BIGSTRING("\pgetcursor"), tabv_getcursor);
    ADD_VERB(BIGSTRING("\pgetselection"), tabv_getselection);
    ADD_VERB(BIGSTRING("\pgo"), tabv_go);
    ADD_VERB(BIGSTRING("\pgoto"), tabv_goto);
    ADD_VERB(BIGSTRING("\pgotoname"), tabv_gotoname);
    ADD_VERB(BIGSTRING("\pjettison"), tabv_jettison);
    ADD_VERB(BIGSTRING("\ppacktable"), tabv_packtable);
    ADD_VERB(BIGSTRING("\pemptytable"), tabv_emptytable);
    ADD_VERB(BIGSTRING("\pgetdisplaysettings"), tabv_getdisplaysettings);
    ADD_VERB(BIGSTRING("\psetdisplaysettings"), tabv_setdisplaysettings);
    ADD_VERB(BIGSTRING("\pgetsortorder"), tabv_getsortorder);

    #undef ADD_VERB

    pophashtable();
    return true;
}
